module tb_TopModule;
    logic clk;
    logic shift_ena;
    logic count_ena;
    logic data;
    logic [3:0] q;

    TopModule uut (
        .clk(clk),
        .shift_ena(shift_ena),
        .count_ena(count_ena),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        shift_ena = 0;
        count_ena = 0;
        data = 0;

        #12;
        // Test shift in: 1, 0, 1, 1 (MSB first -> q should be 4'b1011 = 11)
        shift_ena = 1;
        data = 1; #10;
        data = 0; #10;
        data = 1; #10;
        data = 1; #10;
        shift_ena = 0;

        if (q !== 4'b1011) begin
            $display("SELFTEST FAIL: Shift mismatch. Expected 4'b1011, got %b", q);
            $finish;
        end

        // Test count down
        count_ena = 1;
        #10; // q should be 10 (4'b1010)
        if (q !== 4'b1010) begin
            $display("SELFTEST FAIL: Count down mismatch. Expected 4'b1010, got %b", q);
            $finish;
        end

        #10; // q should be 9 (4'b1001)
        if (q !== 4'b1001) begin
            $display("SELFTEST FAIL: Count down mismatch. Expected 4'b1001, got %b", q);
            $finish;
        end
        count_ena = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
